Tests.EqualCheck("match uppercase letter in [^a-z]", true, matchPattern("HELLO", "[^a-z]"))
Tests.EqualCheck("do not match when string only has lowercase with [^a-z]", false, matchPattern("hello", "[^a-z]"))
Tests.EqualCheck("match non-digit character in [^0-9]", true, matchPattern("item #A", "#[^0-9]"))
Tests.EqualCheck("do not match digit character in [^0-9]", false, matchPattern("item #1", "#[^0-9]"))
Tests.EqualCheck("match character outside subrange [^a-e]", true, matchPattern("cut", "c[^a-e]t"))
Tests.EqualCheck("do not match character inside subrange [^a-e]", false, matchPattern("cat", "c[^a-e]t"))
Tests.EqualCheck("match non-alphanumeric symbol in [^a-zA-Z0-9]", true, matchPattern("hello world", "[^a-zA-Z0-9]"))
Tests.EqualCheck("do not match when string is purely alphanumeric with [^a-zA-Z0-9]", false, matchPattern("hello123", "[^a-zA-Z0-9]"))
Tests.EqualCheck("match punctuation in [^a-zA-Z0-9]", true, matchPattern("code:!42", ":[^a-zA-Z0-9]"))
Tests.EqualCheck("do not match alphanumeric after colon in :[^a-zA-Z0-9]", false, matchPattern("code:x", ":[^a-zA-Z0-9]"))
Tests.EqualCheck("match sequence containing negated range", true, matchPattern("ID_x-9", `ID_[^0-9]-[0-9]`))
Tests.EqualCheck("do not match sequence if negated range contains digit", false, matchPattern("ID_1-9", `ID_[^0-9]-[0-9]`))
Tests.EqualCheck("match whitespace with negated word range", true, matchPattern("a b", `a[^a-zA-Z0-9]b`))
Tests.EqualCheck("match multiple tokens with negated range", true, matchPattern("hello!", `\w\w\w\w\w[^a-z]`))
Tests.EqualCheck("do not match when pattern exceeds line length", false, matchPattern("a", "[^0-9][^0-9]"))
Tests.EqualCheck("empty pattern matches any line", true, matchPattern("hello", ""))
